      "badge:mastery-m04": "M04: 룩 돌파 배지",
      "badge:mastery-m05": "M05: 퀸 지배 배지",
      "badge:mastery-m06": "M06: 킹 수호 배지",
      "badge:mastery-m07": "M07: 전략의 대가",
      "badge:mastery-m08": "M08: 그랜드마스터",
      "badgeFrame:gold": "골드 링",
