export function getCosmeticsCopy(lang?: LanguageCode): CosmeticCopyDict {
  const code = (lang || "en") as LanguageCode;
  const base = COSMETICS_COPY_DICTS[code] || COSMETICS_COPY_DICTS.en;
  const copy = { ...base, options: { ...base.options }, optionConditions: { ...base.optionConditions } };
  const mastery = masteryCopy(code);
  for (const [id, name] of Object.entries(mastery.names)) {
    const key = `badge:mastery-${id.toLowerCase()}`;
    copy.options[key] = name;
    copy.optionConditions[key] = mastery.conditions[id as keyof typeof mastery.names];
  }
  for (const id of BANNER_IDS) {
    copy.options[id] = bannerThemeName(id, code);
    copy.optionConditions[id] = bannerThemeCondition(id, code);
  }
  const milestones = {
    ko: ['숙련도 메달 4개 달성', '숙련도 메달 8개 달성'], en: ['Earn 4 mastery medals', 'Earn 8 mastery medals'],
    ja: ['熟練度メダルを4個獲得', '熟練度メダルを8個獲得'], 'zh-CN': ['获得4枚熟练度奖章', '获得8枚熟练度奖章'],
    de: ['4 Meisterschaftsmedaillen verdienen', '8 Meisterschaftsmedaillen verdienen'], fr: ['Obtenir 4 médailles de maîtrise', 'Obtenir 8 médailles de maîtrise'],
    es: ['Consigue 4 medallas de maestría', 'Consigue 8 medallas de maestría'], ru: ['Получите 4 медали мастерства', 'Получите 8 медалей мастерства'],
    'pt-BR': ['Obtenha 4 medalhas de maestria', 'Obtenha 8 medalhas de maestria'],
  };
  copy.optionConditions['title:explorer'] = milestones[code][0];
  copy.optionConditions['frame:mastery-complete'] = milestones[code][1];
  copy.equippedBadge = { ko: '선택됨', en: 'Selected', ja: '選択中', 'zh-CN': '已选择', de: 'Ausgewählt', fr: 'Sélectionné', es: 'Seleccionado', ru: 'Выбрано', 'pt-BR': 'Selecionado' }[code];
  return copy;
}
